import React, { useState, useEffect } from "react";
import axios from "axios";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";

// Create axios instance with base URL
const api = axios.create({
  baseURL: "http://localhost:5000/api",
  headers: {
    "Content-Type": "application/json",
  },
});

const ViewTasks = () => {
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState({});
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending"
  });
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending"
  });
  const [studentData, setStudentData] = useState(null);
  const [groupData, setGroupData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const user = JSON.parse(localStorage.getItem("users"));

  // Debug function to log API responses
  const debugLog = (endpoint, response) => {
    console.log(`API ${endpoint} response:`, response);
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        // 1. Fetch student data
        const studentRes = await api.get(`/student/user/${user.id}`);
        debugLog("student", studentRes);
        setStudentData(studentRes.data);

        // 2. Fetch group data
        const groupRes = await api.post('/group/student', {
          regNo: studentRes.data.regNo
        });
        debugLog("group", groupRes);
        setGroupData(groupRes.data);

        // 3. Fetch milestones
        const milestonesRes = await api.get(`/milestone/project/${groupRes.data.projectID}`);
        debugLog("milestones", milestonesRes);
        setMilestones(milestonesRes.data);

        // 4. Fetch tasks for each milestone
        const tasksData = {};
        for (const milestone of milestonesRes.data) {
          try {
            const tasksRes = await api.get(`/task/milestone/${milestone._id}`);
            debugLog(`tasks for milestone ${milestone._id}`, tasksRes);
            tasksData[milestone._id] = tasksRes.data;
          } catch (taskError) {
            console.error(`Error fetching tasks for milestone ${milestone._id}:`, taskError);
            tasksData[milestone._id] = [];
          }
        }
        setTasks(tasksData);
      } catch (err) {
        console.error("Data fetching error:", err);
        setError(err.response?.data?.message || err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [user.id]);

  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim()) {
      setError("Please enter a milestone title");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: groupData.projectID
      };

      const response = await api.post('/milestone', milestoneData);
      debugLog("add milestone", response);
      setMilestones([...milestones, response.data]);
      setNewMilestone({ title: "", dueDate: "", status: "Pending" });
      setError(null);
    } catch (err) {
      console.error("Add milestone error:", err);
      setError(err.response?.data?.message || err.message);
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      setError("Please enter a task title");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: studentData.regNo
      };

      const response = await api.post('/task', taskData);
      debugLog("add task", response);

      setTasks(prev => ({
        ...prev,
        [milestoneId]: [...(prev[milestoneId] || []), response.data]
      }));

      setNewTask({ title: "", status: "Pending" });
      setError(null);
    } catch (err) {
      console.error("Add task error:", err);
      setError(err.response?.data?.message || err.message);
    }
  };

  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    try {
      const response = await api.patch(`/task/${taskId}`, {
        status: newStatus,
        completedBy: studentData.regNo
      });
      debugLog("update task", response);

      setTasks(prev => {
        const updatedTasks = { ...prev };
        for (const milestoneId in updatedTasks) {
          updatedTasks[milestoneId] = updatedTasks[milestoneId].map(task => 
            task._id === taskId ? { 
              ...task, 
              status: newStatus,
              completedBy: studentData.regNo 
            } : task
          );
        }
        return updatedTasks;
      });
      setError(null);
    } catch (err) {
      console.error("Update task error:", err);
      setError(err.response?.data?.message || err.message);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;
  if (!studentData?.isGrouped) return <div>Student is not part of any group yet</div>;

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>
          {error && <div className="alert alert-danger">{error}</div>}
          <p className="group-info">Group: {groupData?.groupNo} | Project: {groupData?.projectID}</p>

          {/* Rest of your JSX remains the same */}
          {/* ... */}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
